def cc_plan(cfg,pages,device,qt,nk):
    B,L,HK=cfg['batch'],cfg['q_len'],cfg['num_kv_heads']
    key=(str(device),B,L,HK,pages,cfg['page_size'],cfg['window'],qt,nk)
    if key not in cc__PLANS:
        groups=B*HK*qt
